import { muatProduk, renderProduk } from './katalog.js';
import { pasangPencarian, siapkanIndeks } from './pencarian.js';
import { pasangKeranjang, siapkanRiwayatContoh } from './keranjang.js';
import { pasangVoucher } from './harga-promo.js';
import { pasangPromo } from './promo.js';
import { pasangGulir } from './gulir.js';
import { pasangKaki } from './kategori.js';
import { kirimTertunda, mulaiTelemetri } from './telemetri.js';

async function mulai() {
  mulaiTelemetri();
  pasangPromo();
  pasangGulir();

  const produk = await muatProduk();
  siapkanRiwayatContoh(produk);

  pasangPencarian();
  pasangKeranjang();
  pasangVoucher();
  pasangKaki(produk);
  renderProduk(produk);
  siapkanIndeks(produk);

  if (window.Lacak) kirimTertunda('page_view', { halaman: 'flashsale-1212', jumlahProduk: produk.length });
}

mulai();

// Alat ukur untuk tugas: aktif jika URL diberi ?ukur=1
if (new URLSearchParams(location.search).has('ukur')) {
  import('/alat/ukur.js');
}

// Keranjang belanja, riwayat penelusuran, dan "Beli sekarang".
// Semua disimpan di localStorage supaya tetap ada walau halaman dimuat ulang.

import { $, el, formatRupiah, hargaSetelahDiskon, salinDalam, tampilkanToast } from './util.js';
import { kirimTertunda } from './telemetri.js';

const KUNCI_KERANJANG = 'tk_keranjang';
const KUNCI_RIWAYAT = 'tk_riwayat';

const KONFIG = { maksPerProduk: 99, mataUang: 'IDR', sumber: 'web-flashsale-1212' };

function bacaKeranjang() {
  return JSON.parse(localStorage.getItem(KUNCI_KERANJANG) || '[]');
}
function simpanKeranjang(isi) {
  localStorage.setItem(KUNCI_KERANJANG, JSON.stringify(isi));
}

// Riwayat disimpan di memori setelah dibaca sekali. Sebelumnya tiap klik
// memanggil JSON.parse atas ~9000 entri, dan seluruh array itu ikut dikirim
// ke SDK analitik (yang menghitung hash O(12 x panjang string)) sehingga satu
// klik "+ Keranjang" membekukan main thread.
let riwayatMemori = null;

function bacaRiwayat() {
  if (riwayatMemori === null) riwayatMemori = JSON.parse(localStorage.getItem(KUNCI_RIWAYAT) || '[]');
  return riwayatMemori;
}

// Penulisan riwayat (~9000 entri, ~1 MB) ke localStorage ditunda: memori jadi
// sumber kebenaran, dan stringify besar tidak dijalankan di jalur kritis klik.
let pengaturSimpanRiwayat;
function simpanRiwayat(riwayat) {
  riwayatMemori = riwayat;
  clearTimeout(pengaturSimpanRiwayat);
  pengaturSimpanRiwayat = setTimeout(() => {
    localStorage.setItem(KUNCI_RIWAYAT, JSON.stringify(riwayatMemori));
  }, 400);
}

// Riwayat aktivitas dipakai tim rekomendasi ("Karena kamu melihat...").
// Untuk pengembangan, kita isi dengan data contoh pelanggan lama yang aktif
// sejak 2023 supaya kondisinya mirip pengguna sungguhan.
export function siapkanRiwayatContoh(semuaProduk) {
  if (localStorage.getItem(KUNCI_RIWAYAT)) return;
  const riwayat = [];
  const jenis = ['lihat', 'lihat', 'lihat', 'cari', 'keranjang', 'beli'];
  let waktu = Date.parse('2023-01-05T08:00:00+07:00');
  for (let i = 0; i < 9000; i++) {
    const p = semuaProduk[(i * 131) % semuaProduk.length];
    waktu += 1000 * 60 * (7 + (i % 190));
    riwayat.push({ t: waktu, jenis: jenis[i % jenis.length], id: p.id, nama: p.nama, kategori: p.kategori, harga: p.harga });
  }
  simpanRiwayat(riwayat);
}

export function perbaruiLencana() {
  const total = bacaKeranjang().reduce((n, item) => n + item.jumlah, 0);
  $('#lencana-keranjang').textContent = total;
}

function gambarPanel() {
  const daftar = $('#daftar-keranjang');
  const isi = bacaKeranjang();
  daftar.innerHTML = '';
  let total = 0;
  if (isi.length === 0) daftar.append(el('li', '', 'Keranjang masih kosong. Tambahkan produk dari daftar.'));
  for (const item of isi) {
    total += item.harga * item.jumlah;
    const baris = el('li');
    baris.append(el('span', '', item.nama), el('span', 'jumlah', item.jumlah + ' x ' + formatRupiah(item.harga)));
    const hapus = el('button', 'hapus', 'Hapus dari keranjang');
    hapus.type = 'button';
    hapus.addEventListener('click', () => {
      simpanKeranjang(bacaKeranjang().filter((x) => x.id !== item.id));
      perbaruiLencana();
      gambarPanel();
    });
    baris.append(hapus);
    daftar.append(baris);
  }
  $('#total-keranjang').textContent = formatRupiah(total);
}

export function tambahKeKeranjang(produk, tombol) {
  const konfig = salinDalam(KONFIG);
  const keranjang = bacaKeranjang();
  const riwayat = bacaRiwayat();

  const ada = keranjang.find((item) => item.id === produk.id);
  if (ada) ada.jumlah = Math.min(ada.jumlah + 1, konfig.maksPerProduk);
  else keranjang.push({ id: produk.id, nama: produk.nama, harga: hargaSetelahDiskon(produk), jumlah: 1 });

  riwayat.push({ t: Date.now(), jenis: 'keranjang', id: produk.id, nama: produk.nama, kategori: produk.kategori, harga: produk.harga });

  // Event tetap terkirim dengan konteks yang masuk akal, tetapi tanpa
  // menyertakan seluruh riwayat (9000 entri). Mengirim array raksasa membuat
  // SDK menghitung hash O(12 x panjang string) dan membekukan main thread.
  const totalItem = keranjang.reduce((n, item) => n + item.jumlah, 0);
  kirimTertunda('add_to_cart', {
    id: produk.id,
    nama: produk.nama,
    harga: hargaSetelahDiskon(produk),
    jumlahKeranjang: ada ? ada.jumlah : 1,
    totalItem,
    sumber: konfig.sumber,
  });

  simpanKeranjang(keranjang);
  simpanRiwayat(riwayat);

  // Data sudah aman tersimpan, baru tampilan diperbarui.
  perbaruiLencana();
  tombol.textContent = 'Ditambahkan ✓';
  tombol.classList.add('sudah');
  setTimeout(() => {
    tombol.textContent = '+ Keranjang';
    tombol.classList.remove('sudah');
  }, 1500);
  tampilkanToast('Ditambahkan ke keranjang: ' + produk.nama);
}

// Penjaga per produk: selama satu permintaan "Beli sekarang" masih berjalan,
// klik berikutnya diabaikan. Mencegah pesanan ganda dari klik beruntun.
const sedangDipesan = new Set();

export async function beliSekarang(produk, tombol) {
  if (sedangDipesan.has(produk.id)) return; // sudah ada permintaan berjalan -> tepat 1 pesanan
  sedangDipesan.add(produk.id);

  const konfig = salinDalam(KONFIG);
  const riwayat = bacaRiwayat();
  riwayat.push({ t: Date.now(), jenis: 'beli', id: produk.id, nama: produk.nama, kategori: produk.kategori, harga: produk.harga });
  kirimTertunda('begin_checkout', {
    id: produk.id,
    nama: produk.nama,
    harga: hargaSetelahDiskon(produk),
    sumber: konfig.sumber,
  });
  simpanRiwayat(riwayat);

  // Beri umpan balik segera supaya pengguna tahu pesanannya sedang diproses.
  tombol.disabled = true;
  tombol.textContent = 'Memproses…';

  try {
    const respons = await fetch('/api/pesanan', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ produkId: produk.id, nama: produk.nama }),
    });
    const pesanan = await respons.json();

    tombol.textContent = 'Dipesan ✓';
    tampilkanToast('Pesanan ' + pesanan.id + ' dibuat: ' + produk.nama);
    await perbaruiLencanaPesanan();
  } finally {
    sedangDipesan.delete(produk.id);
    tombol.disabled = false;
    setTimeout(() => { tombol.textContent = 'Beli sekarang'; }, 1500);
  }
}

export async function perbaruiLencanaPesanan() {
  const respons = await fetch('/api/pesanan');
  const pesanan = await respons.json();
  $('#lencana-pesanan').textContent = pesanan.length;
  return pesanan;
}

export function pasangKeranjang() {
  const panel = $('#panel-keranjang');
  const tombolBuka = $('#tombol-keranjang');
  const buka = (ya) => {
    panel.hidden = !ya;
    tombolBuka.setAttribute('aria-expanded', String(ya));
    if (ya) gambarPanel();
  };
  tombolBuka.addEventListener('click', () => buka(panel.hidden));
  $('#tutup-keranjang').addEventListener('click', () => buka(false));
  $('#kosongkan-keranjang').addEventListener('click', () => {
    simpanKeranjang([]);
    perbaruiLencana();
    gambarPanel();
  });

  $('#tombol-pesanan').addEventListener('click', async () => {
    const pesanan = await perbaruiLencanaPesanan();
    if (pesanan.length === 0) return tampilkanToast('Belum ada pesanan. Tekan "Beli sekarang" pada produk untuk memesan.');
    const terakhir = pesanan.slice(-3).map((p) => p.id + ' (produk #' + p.produkId + ')').join(', ');
    tampilkanToast(pesanan.length + ' pesanan. Terakhir: ' + terakhir);
  });

  perbaruiLencana();
  perbaruiLencanaPesanan();
}

// Pencarian, saringan kategori, dan pengurutan.

import { $, el, debounce, hargaSetelahDiskon } from './util.js';
import { kirimTertunda } from './telemetri.js';
import { keadaan, renderProduk } from './katalog.js';

const saringan = { kata: '', kategori: 'Semua', urut: 'relevan' };

// "Sepatu Lari" == "sepatu  lari" == "SEPATU-LARI"
function normalkan(teks) {
  return teks
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

// Teks pencarian tiap produk dinormalkan sekali lalu di-cache, supaya
// normalkan() (regex atas string panjang) tidak dijalankan ulang untuk
// seluruh katalog pada setiap ketikan.
const teksTernormal = new WeakMap();

function teksProduk(produk) {
  let teks = teksTernormal.get(produk);
  if (teks === undefined) {
    teks = normalkan(produk.nama + ' ' + produk.merek + ' ' + produk.kategori + ' ' + produk.kota);
    teksTernormal.set(produk, teks);
  }
  return teks;
}

function cocok(produk, kunci) {
  return kunci.split(' ').every((k) => teksProduk(produk).includes(k));
}

// Bangun indeks teks untuk seluruh katalog secara bertahap (per-chunk lewat
// macrotask). Kalau tidak, pencarian pertama menanggung normalisasi 3000 produk
// sekaligus (~40 ms, jadi ~160 ms pada CPU 4x) sehingga menjadi long task.
export function siapkanIndeks(produk) {
  let i = 0;
  const langkah = () => {
    const batas = Math.min(i + 300, produk.length);
    for (; i < batas; i++) teksProduk(produk[i]);
    if (i < produk.length) setTimeout(langkah, 0);
  };
  langkah();
}

const PEMBANDING = {
  murah: (a, b) => hargaSetelahDiskon(a) - hargaSetelahDiskon(b),
  mahal: (a, b) => hargaSetelahDiskon(b) - hargaSetelahDiskon(a),
  laris: (a, b) => b.terjual - a.terjual,
  rating: (a, b) => b.rating - a.rating || b.terjual - a.terjual,
};

export function terapkanSaringan() {
  const kunci = normalkan(saringan.kata);
  let hasil = keadaan.semuaProduk.filter((p) => {
    if (saringan.kategori !== 'Semua' && p.kategori !== saringan.kategori) return false;
    if (kunci && !cocok(p, kunci)) return false;
    return true;
  });
  if (PEMBANDING[saringan.urut]) hasil = hasil.slice().sort(PEMBANDING[saringan.urut]);
  renderProduk(hasil);

  if (kunci) kirimTertunda('search', { kata: saringan.kata, jumlah: hasil.length });
}

export function pasangPencarian() {
  const kolom = $('#kolom-cari');
  // Debounce: tiap huruf tidak lagi memicu render ulang seluruh kisi; render
  // dijalankan setelah ketikan berhenti sejenak, sehingga tiap task pendek dan
  // browser tetap punya rendering opportunity -> INP turun.
  const terapkanTertunda = debounce(() => terapkanSaringan(), 150);
  kolom.addEventListener('input', () => {
    saringan.kata = kolom.value;
    terapkanTertunda();
  });

  $('#pilih-urut').addEventListener('change', (e) => {
    saringan.urut = e.target.value;
    terapkanSaringan();
  });

  const wadah = $('#keping-kategori');
  const kategori = ['Semua', ...new Set(keadaan.semuaProduk.map((p) => p.kategori))];
  for (const nama of kategori) {
    const keping = el('button', 'keping', nama);
    keping.type = 'button';
    keping.setAttribute('aria-pressed', String(nama === 'Semua'));
    keping.addEventListener('click', () => {
      saringan.kategori = nama;
      wadah.querySelectorAll('.keping').forEach((k) => k.setAttribute('aria-pressed', String(k === keping)));
      terapkanSaringan();
    });
    wadah.append(keping);
  }
}

// Voucher: menghitung harga promo untuk setiap produk.
// Aturan promo bertingkat + simulasi cicilan ditentukan tim bisnis.

import { $, hargaSetelahDiskon, tampilkanToast } from './util.js';
import { kirimTertunda } from './telemetri.js';
import { keadaan, perbaruiHargaVoucherDiKartu } from './katalog.js';

const VOUCHER = {
  KILAT1212: { persen: 12, maksPotongan: 120000, minBelanja: 50000 },
  HEMAT50: { persen: 5, maksPotongan: 50000, minBelanja: 0 },
};

// Cicilan 0% sampai 24 bulan: cari tenor dengan angsuran paling ringan yang
// masih memenuhi batas minimal angsuran per bulan dari mitra pembiayaan.
function simulasiCicilan(harga) {
  let terbaik = { tenor: 1, angsuran: harga };
  for (let tenor = 1; tenor <= 24; tenor++) {
    let sisa = harga;
    let angsuran = Math.ceil(harga / tenor / 100) * 100;
    for (let bulan = 1; bulan <= tenor; bulan++) {
      const biayaAdmin = Math.round(sisa * 0.0005 * Math.log2(bulan + 1));
      sisa = sisa - angsuran + biayaAdmin;
      if (sisa < 0) sisa = 0;
    }
    angsuran += Math.ceil(sisa / tenor);
    if (angsuran >= 25000 && angsuran < terbaik.angsuran) terbaik = { tenor, angsuran };
  }
  return terbaik;
}

// Perhitungan harga promo untuk satu produk. Dipakai langsung (sinkron);
// pemanggil yang mengatur agar tidak memblokir halaman dengan memproses
// per-chunk dan memberi kesempatan browser menggambar di antaranya.
function hitungHargaPromo(produk, aturan) {
  const dasar = hargaSetelahDiskon(produk);
  if (dasar < aturan.minBelanja) return null;
  let potongan = Math.min(Math.round((dasar * aturan.persen) / 100), aturan.maksPotongan);
  if (produk.flashSale) potongan = Math.round(potongan / 2); // flash sale hanya dapat setengah
  const hargaAkhir = Math.max(dasar - potongan, 100);
  const cicilan = simulasiCicilan(hargaAkhir);
  return { hargaAkhir, cicilan };
}

const UKURAN_CHUNK = 150;

async function terapkanVoucher(kode) {
  const aturan = VOUCHER[kode];
  if (!aturan) {
    tampilkanToast('Kode voucher "' + kode + '" tidak dikenal. Coba KILAT1212.');
    return;
  }

  const progres = $('#progres');
  const isi = $('#progres-isi');
  const teks = $('#progres-teks');
  progres.hidden = false;
  isi.style.width = '0%';

  const total = keadaan.semuaProduk.length;
  let selesai = 0;
  keadaan.hargaVoucher.clear();

  // Diproses per-chunk. Setelah tiap chunk kita menunggu macrotask
  // (setTimeout), BUKAN microtask. Microtask dikuras habis sebelum browser
  // sempat menggambar, sehingga progress bar membeku di 0% lalu melompat ke
  // 100% (keluhan TK-1057). Macrotask memberi rendering opportunity sehingga
  // progres tergambar bertahap dan kolom cari tetap responsif.
  for (let i = 0; i < total; i += UKURAN_CHUNK) {
    const batas = Math.min(i + UKURAN_CHUNK, total);
    for (let j = i; j < batas; j++) {
      const hasil = hitungHargaPromo(keadaan.semuaProduk[j], aturan);
      if (hasil) keadaan.hargaVoucher.set(keadaan.semuaProduk[j].id, hasil.hargaAkhir);
      selesai++;
    }
    const persen = Math.round((selesai / total) * 100);
    isi.style.width = persen + '%';
    teks.textContent = 'Menghitung harga promo… ' + persen + '% (' + selesai + ' dari ' + total + ' produk)';
    await new Promise((r) => setTimeout(r, 0));
  }

  perbaruiHargaVoucherDiKartu();
  progres.hidden = true;
  tampilkanToast('Voucher ' + kode + ' dipakai di ' + keadaan.hargaVoucher.size.toLocaleString('id-ID') + ' produk.');
  kirimTertunda('apply_voucher', { kode, jumlah: keadaan.hargaVoucher.size });
}

export function pasangVoucher() {
  const kolom = $('#kolom-voucher');
  $('#tombol-voucher').addEventListener('click', () => terapkanVoucher(kolom.value.trim().toUpperCase()));
  kolom.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') terapkanVoucher(kolom.value.trim().toUpperCase());
  });
}

// Katalog: menyimpan data produk dan menggambar kisi kartu produk.

import { $, el, formatRupiah, formatRibuan, hargaSetelahDiskon } from './util.js';
import { tambahKeKeranjang, beliSekarang } from './keranjang.js';
import { periksaGulir, amatiKartu, lupakanKartu, perbaruiTinggiDokumen } from './gulir.js';

export const keadaan = {
  semuaProduk: [],
  ditampilkan: [],
  hargaVoucher: new Map(), // id produk -> harga setelah voucher
};

// --- penggambaran bertahap (windowing) ---
// Semua produk tetap ada di keadaan.ditampilkan dan dihitung di ringkasan,
// tetapi hanya sebagian kartu yang diletakkan di DOM. Sisa kartu ditambahkan
// ketika sentinel di ujung kisi mendekati layar. Ukuran chunk dibuat kecil (24)
// supaya tiap task pembuatan kartu tetap < 100 ms walau pada CPU 4x.
const UKURAN_CHUNK = 24;
let daftarAktif = [];
let posisiChunk = 0;
let sentinel = null;
let pengamatSentinel = null;

export async function muatProduk() {
  const respons = await fetch('/api/produk');
  keadaan.semuaProduk = await respons.json();
  return keadaan.semuaProduk;
}

function buatKartu(produk) {
  const kartu = el('article', 'kartu');
  kartu.dataset.id = produk.id;

  if (produk.flashSale) kartu.append(el('span', 'lencana-kilat', '⚡ Kilat'));

  const media = el('a', 'kartu-media');
  media.href = '#produk-' + produk.id;
  const gambar = document.createElement('img');
  gambar.src = produk.gambar;
  gambar.alt = produk.nama;
  // Muat gambar hanya ketika mendekati layar (kuota & CPU), dan beri tahu
  // browser rasio aspek (SVG server selalu 480x480) agar ruangnya sudah
  // dialokasikan sebelum gambar tiba -> tidak ada layout shift.
  gambar.loading = 'lazy';
  gambar.decoding = 'async';
  gambar.width = 480;
  gambar.height = 480;
  media.append(gambar);

  const badan = el('div', 'kartu-badan');
  const judul = el('h3', 'kartu-judul', produk.nama);
  badan.append(judul);

  const harga = el('div', 'harga');
  harga.append(el('span', 'harga-kini', formatRupiah(hargaSetelahDiskon(produk))));
  if (produk.diskon > 0) {
    harga.append(el('span', 'harga-asli', formatRupiah(produk.harga)));
    harga.append(el('span', 'harga-diskon', '-' + produk.diskon + '%'));
  }
  const hargaVoucher = keadaan.hargaVoucher.get(produk.id);
  if (hargaVoucher) harga.append(el('span', 'harga-voucher', 'Pakai voucher: ' + formatRupiah(hargaVoucher)));
  badan.append(harga);

  badan.append(el('div', 'keterangan', '★ ' + produk.rating.toLocaleString('id-ID') + ' | ' + formatRibuan(produk.terjual) + ' terjual'));
  badan.append(el('div', 'keterangan', produk.kota));

  const aksi = el('div', 'aksi');
  const tombolTambah = el('button', 'tombol-tambah', '+ Keranjang');
  tombolTambah.type = 'button';
  tombolTambah.addEventListener('click', () => tambahKeKeranjang(produk, tombolTambah));
  const tombolBeli = el('button', 'tombol-beli', 'Beli sekarang');
  tombolBeli.type = 'button';
  tombolBeli.addEventListener('click', () => beliSekarang(produk, tombolBeli));
  aksi.append(tombolTambah, tombolBeli);
  badan.append(aksi);

  kartu.append(media, badan);
  return kartu;
}

// Judul produk panjangnya beda-beda (1-3 baris). Supaya harga & tombol dalam
// satu deret sejajar rapi, tinggi judul disamakan. Cara lama mengukur tinggi
// judul lalu menulisnya ke setiap elemen (baca offsetHeight + tulis style) yang
// memaksa reflow dan memakan ~83 ms pada CPU 4x. Diganti dengan pembatasan 2
// baris lewat CSS (.kartu-judul): tinggi tetap seragam tanpa pengukuran sama
// sekali, sehingga tak ada reflow dan tak ada long task saat menggambar kartu.
function pastikanSentinel(kisi) {
  if (!sentinel) {
    sentinel = el('div', 'sentinel');
    pengamatSentinel = new IntersectionObserver((entri) => {
      if (entri.some((e) => e.isIntersecting)) { tambahChunk(); isiSampaiLayarPenuh(); }
    }, { rootMargin: '800px 0px' });
  }
  kisi.append(sentinel);
  pengamatSentinel.observe(sentinel);
}

function tambahChunk() {
  const kisi = $('#kisi');
  if (posisiChunk >= daftarAktif.length) return;
  const batas = Math.min(posisiChunk + UKURAN_CHUNK, daftarAktif.length);
  const frag = document.createDocumentFragment();
  for (; posisiChunk < batas; posisiChunk++) {
    const kartu = buatKartu(daftarAktif[posisiChunk]);
    amatiKartu(kartu);
    frag.append(kartu);
  }
  kisi.append(frag);
  if (sentinel && sentinel.parentNode === kisi) kisi.append(sentinel); // jaga sentinel di ujung
  perbaruiTinggiDokumen();
}

export function renderProduk(daftar) {
  const kisi = $('#kisi');
  keadaan.ditampilkan = daftar;
  daftarAktif = daftar;
  posisiChunk = 0;
  lupakanKartu();
  kisi.innerHTML = '';

  if (daftar.length === 0) {
    const kosong = el('div', 'kosong');
    kosong.append(el('strong', '', 'Produk tidak ditemukan.'), el('p', '', 'Periksa ejaan, atau coba kata kunci yang lebih umum seperti "sepatu" atau "serum".'));
    kisi.append(kosong);
  } else {
    pastikanSentinel(kisi);
    // Isi sampai layar terisi; sisanya ditangani pengamat sentinel saat menggulir.
    tambahChunk();
    isiSampaiLayarPenuh();
  }

  // Ringkasan selalu melaporkan jumlah hasil yang sebenarnya, bukan jumlah kartu di DOM.
  $('#ringkasan').textContent = daftar.length.toLocaleString('id-ID') + ' produk ditampilkan';
  periksaGulir();
}

// Isi sampai layar terisi. Pemeriksaan posisi sentinel dilakukan di frame
// berikutnya (requestAnimationFrame), BUKAN di dalam task render. Membaca
// getBoundingClientRect tepat setelah menambah puluhan kartu memaksa layout
// sinkron (~89 ms pada CPU 4x) dan menjadikan task render sebuah long task.
function isiSampaiLayarPenuh() {
  if (posisiChunk >= daftarAktif.length) return;
  requestAnimationFrame(() => {
    if (posisiChunk >= daftarAktif.length || !sentinel || !sentinel.isConnected) return;
    if (sentinel.getBoundingClientRect().top < window.innerHeight + 800) {
      tambahChunk();
      isiSampaiLayarPenuh();
    }
  });
}

// Perbarui harga voucher hanya pada kartu yang benar-benar ada di DOM,
// tanpa menggambar ulang seluruh kisi (yang akan membuang posisi gulir).
export function perbaruiHargaVoucherDiKartu() {
  document.querySelectorAll('.kartu').forEach((kartu) => {
    const harga = keadaan.hargaVoucher.get(Number(kartu.dataset.id));
    const baris = kartu.querySelector('.harga');
    let label = kartu.querySelector('.harga-voucher');
    if (harga) {
      if (!label) { label = el('span', 'harga-voucher'); baris.append(label); }
      label.textContent = 'Pakai voucher: ' + formatRupiah(harga);
    } else if (label) {
      label.remove();
    }
  });
}

// Elemen kampanye: hitung mundur, teks berjalan, dan banner promo.

import { $, el, tampilkanToast } from './util.js';
import { kirimTertunda } from './telemetri.js';

// Flash sale berakhir tengah malam nanti (waktu perangkat).
function akhirFlashSale() {
  const t = new Date();
  t.setHours(24, 0, 0, 0);
  return t.getTime();
}

const duaDigit = (n) => String(n).padStart(2, '0');

function pasangHitungMundur() {
  const akhir = akhirFlashSale();
  const awal = Date.now();
  const garis = $('#hm-garis');
  const jam = $('#hm-jam'), menit = $('#hm-menit'), detik = $('#hm-detik'), senti = $('#hm-senti');

  const rentang = akhir - awal + 1;
  const nilaiTerakhir = { jam: '', menit: '', detik: '', senti: '', rasio: -1 };

  const segarkan = () => {
    const sisa = Math.max(akhir - Date.now(), 0);
    const j = duaDigit(Math.floor(sisa / 3600000));
    const m = duaDigit(Math.floor((sisa % 3600000) / 60000));
    const d = duaDigit(Math.floor((sisa % 60000) / 1000));
    const s = duaDigit(Math.floor((sisa % 1000) / 10));
    // Tulis ke DOM hanya bila nilainya berubah (hindari kerja sia-sia).
    if (j !== nilaiTerakhir.jam) { jam.textContent = j; nilaiTerakhir.jam = j; }
    if (m !== nilaiTerakhir.menit) { menit.textContent = m; nilaiTerakhir.menit = m; }
    if (d !== nilaiTerakhir.detik) { detik.textContent = d; nilaiTerakhir.detik = d; }
    if (s !== nilaiTerakhir.senti) { senti.textContent = s; nilaiTerakhir.senti = s; }

    // Garis menyusut lewat transform: scaleX (tidak memicu layout/paint ulang).
    const rasio = Math.round((sisa / rentang) * 1000) / 1000;
    if (rasio !== nilaiTerakhir.rasio) {
      garis.style.transform = 'scaleX(' + rasio + ')';
      nilaiTerakhir.rasio = rasio;
    }
  };

  // 50 ms: perseratus detik masih terbaca, tetapi jumlah task main thread saat
  // diam turun 5x dibanding 10 ms dan tanpa reflow paksa.
  let pengatur;
  const mulai = () => { if (!pengatur) pengatur = setInterval(segarkan, 50); };
  const hentikan = () => { clearInterval(pengatur); pengatur = null; };
  document.addEventListener('visibilitychange', () => (document.hidden ? hentikan() : mulai()));
  segarkan();
  mulai();
}

// Teks berjalan kini dianimasikan CSS (lihat .berjalan-jalur di toko.css),
// sehingga bergerak di compositor thread dan tidak membebani main thread.
function pasangTeksBerjalan() {
  const teks = $('#berjalan-teks');
  if (teks && !teks.dataset.jalan) {
    teks.dataset.jalan = '1';
    teks.parentElement.classList.add('berjalan-aktif');
  }
}

async function pasangBannerPromo() {
  // Sisipkan struktur banner SECARA SINKRON (skeleton) sebelum data tiba,
  // lalu isi teksnya di tempat. Karena node & tata letaknya sudah ada lebih
  // dulu, tidak ada konten yang bergeser ketika data promo tiba (CLS ~0).
  const banner = el('section', 'promo-banner');
  const teks = el('div');
  const judul = el('h2', '', 'Memuat promo…');
  const isi = el('p', '', 'Mohon tunggu, sedang mengambil syarat dan ketentuan promo.');
  teks.append(judul, isi);
  const tombol = el('button', '', 'Lihat syarat promo');
  tombol.type = 'button';
  banner.append(teks, tombol);
  $('#utama').prepend(banner);

  const respons = await fetch('/api/promo');
  const promo = await respons.json();

  judul.textContent = promo.judul;
  isi.textContent = promo.isi;
  tombol.textContent = promo.tombol;
  tombol.addEventListener('click', () => {
    tampilkanToast('Syarat promo: berlaku 12 Desember, satu voucher per akun, tidak bisa digabung.');
    kirimTertunda('promo_click', { judul: promo.judul });
  });
}

export function pasangPromo() {
