  pasangTeksBerjalan();
  pasangBannerPromo();
}

// Perilaku saat halaman digulir: bayangan header, bar progres baca,
// tombol "Ke atas", efek kartu muncul, dan pencatatan impresi produk.

import { $, rafThrottle } from './util.js';
import { kirimImpresi } from './telemetri.js';

const sudahTercatat = new Set();
let pengamatKartu = null;

// Satu IntersectionObserver untuk semua kartu: memunculkan kartu (animasi)
// dan mencatat impresi saat kartu masuk layar. Ini menggantikan pemindaian
// querySelectorAll('.kartu') + getBoundingClientRect() pada tiap event gulir,
// yang memaksa layout sinkron (reflow) berulang -> penyebab gulir patah-patah.
function pengamatKartuSekali() {
  if (pengamatKartu) return pengamatKartu;
  pengamatKartu = new IntersectionObserver((entri) => {
    const impresiBaru = [];
    for (const e of entri) {
      if (!e.isIntersecting) continue; // masih di luar layar, tetap dipantau
      const kartu = e.target;
      if (!kartu.classList.contains('terlihat')) kartu.classList.add('terlihat');
      const id = kartu.dataset.id;
      if (id && !sudahTercatat.has(id)) {
        sudahTercatat.add(id);
        impresiBaru.push(id);
      }
      // Sudah pernah terlihat & tercatat -> tidak perlu dipantau lagi.
      pengamatKartu.unobserve(kartu);
    }
    if (impresiBaru.length) kirimImpresi(impresiBaru);
  }, { rootMargin: '80px 0px 80px 0px' });
  return pengamatKartu;
}

// Dipanggil katalog setiap kartu baru dibuat.
export function amatiKartu(kartu) {
  pengamatKartuSekali().observe(kartu);
}

// Dipanggil katalog sebelum kisi digambar ulang: lepaskan observer lama agar
// kartu-kartu yang dibuang tidak menumpuk sebagai target di memori.
export function lupakanKartu() {
  if (pengamatKartu) { pengamatKartu.disconnect(); pengamatKartu = null; }
}

// Bagian yang bergantung posisi gulir (header, bar baca, tombol ke atas).
// Dijalankan paling banyak sekali per frame lewat rafThrottle. Tinggi dokumen
// TIDAK dibaca tiap frame (scrollHeight memaksa reflow, ~216 ms terukur di CPU
// 4x saat gulir). Tinggi di-cache dan disegarkan hanya ketika konten berubah
// (setelah render/chunk) atau saat resize, bukan lewat timer berkala (timer
// memicu reflow saat halaman diam -> merusak S0/S6).
let tinggiDokumen = 0;
export function perbaruiTinggiDokumen() {
  tinggiDokumen = document.documentElement.scrollHeight - window.innerHeight;
}
window.addEventListener('resize', perbaruiTinggiDokumen, { passive: true });

const perbaruiBilah = rafThrottle(() => {
  const kepala = $('#kepala');
  const bar = $('#bar-gulir');
  const keAtas = $('#ke-atas');

  const y = window.scrollY;
  kepala.classList.toggle('melayang', y > 8);
  keAtas.hidden = y < 900;

  const rasio = tinggiDokumen > 0 ? y / tinggiDokumen : 0;
  // Pakai transform: scaleX (tidak memicu layout) alih-alih menulis width.
  bar.style.transform = 'scaleX(' + rasio + ')';
});

// Nama lama dipertahankan supaya pemanggil (katalog) tidak perlu diubah.
export function periksaGulir() {
  perbaruiBilah();
}

export function pasangGulir() {
  window.addEventListener('scroll', perbaruiBilah, { passive: true });
  window.addEventListener('resize', perbaruiBilah, { passive: true });
  perbaruiTinggiDokumen();

  // Cegah "pull to refresh" tak sengaja di Android ketika pengguna sedang di puncak halaman.
  let yAwal = 0;
  const utama = $('#utama');
  utama.addEventListener('touchstart', (e) => { yAwal = e.touches[0].clientY; }, { passive: true });
  utama.addEventListener('touchmove', (e) => {
    const menarikKeBawah = e.touches[0].clientY > yAwal;
    if (window.scrollY === 0 && menarikKeBawah) e.preventDefault();
  }, { passive: false });

  $('#ke-atas').addEventListener('click', () => window.scrollTo({ top: 0 }));
}

// Bagian kaki halaman: merek paling laris & kategori yang sering dibeli bersamaan.

import { $, el, urutkanGelembung } from './util.js';

export function pasangKaki(semuaProduk) {
  // --- merek paling laris ---
  const terjualPerMerek = {};
  for (const p of semuaProduk) terjualPerMerek[p.merek] = (terjualPerMerek[p.merek] || 0) + p.terjual;
  const merek = Object.keys(terjualPerMerek).map((nama) => ({ nama, terjual: terjualPerMerek[nama] }));
  const teratas = urutkanGelembung(merek, (a, b) => b.terjual - a.terjual).slice(0, 5);
  const daftarMerek = $('#merek-populer');
  for (const m of teratas) daftarMerek.append(el('li', '', m.nama + ' (' + m.terjual.toLocaleString('id-ID') + ' terjual)'));

  // --- kategori terkait ---
  // Nilai "sudahAda" pada kode lama adalah jumlah <li> yang sudah ditambahkan,
  // yang pada iterasi ke-i selalu sama dengan i. Jadi pembacaan DOM
  // (querySelectorAll di dalam loop) tidak diperlukan dan diganti dengan i,
  // sehingga hasilnya identik tanpa memaksa reflow tiap iterasi.
  const kategori = [...new Set(semuaProduk.map((p) => p.kategori))];
  const daftarTerkait = $('#kategori-terkait');
  const frag = document.createDocumentFragment();
  for (let i = 0; i < kategori.length; i++) {
    let pasangan = null;
    let skorTertinggi = -1;
    for (let j = 0; j < kategori.length; j++) {
      if (i === j) continue;
      const skor = ((kategori[i].length * 31 + kategori[j].length * 17 + i) % 97);
      if (skor > skorTertinggi) { skorTertinggi = skor; pasangan = kategori[j]; }
    }
    frag.append(el('li', '', kategori[i] + ' + ' + pasangan));
  }
  daftarTerkait.append(frag);
}

// Semua pemanggilan SDK analitik lewat modul ini.
//
// Akar masalah yang terukur: satu panggilan Lacak.kirim menghitung hash tetap
// 2.000.000 iterasi (lihat F=2000000 di lacak.min.js), jadi biayanya ~90 ms
// pada CPU 4x TERLEPAS dari ukuran payload, dan itu memblokir main thread.
// Karena itu SDK dijalankan di Web Worker (lihat lacak-pekerja.js) supaya
// hashing keluar dari main thread; modul ini menjadi jembatan ke worker itu.
//
// Selain itu: panggilan yang dipicu interaksi ditunda ke macrotask berikutnya,
// dan event impression digabung lalu dikirim sekali saat gulir berhenti.

let pekerja = null;

function inisialisasiPekerja() {
  if (pekerja) return;
  try {
    pekerja = new Worker('/js/lacak-pekerja.js');
    pekerja.onerror = () => { pekerja = null; }; // fallback ke main thread
    pekerja.postMessage({
      init: {
        pathname: location.pathname,
        screen: { width: screen.width, height: screen.height, colorDepth: screen.colorDepth },
      },
    });
  } catch {
    pekerja = null;
  }
}

function kirim(nama, data) {
  if (pekerja) {
    pekerja.postMessage({ nama, data });
    return;
  }
  // Fallback: main thread (mis. Worker tidak tersedia).
  if (window.Lacak) window.Lacak.kirim(nama, data);
}

// Untuk event tunggal (search, add_to_cart, begin_checkout, apply_voucher,
// promo_click, page_view): tetap dikirim, tetapi keluar dari task interaksi.
export function kirimTertunda(nama, data) {
  setTimeout(() => kirim(nama, data), 0);
}

// --- penggabungan impresi ---
const antreanImpresi = new Set();
let pengaturImpresi = null;
let waktuFlushTerakhir = Date.now();
const JEDA_DIAM = 500;      // kirim setelah gulir berhenti sejenak
const MAKS_MENAHAN = 6000;  // jaminan: tetap dikirim minimal tiap 6 detik

export function kirimImpresi(ids) {
  if (!ids.length) return;
  for (const id of ids) antreanImpresi.add(id);
  jadwalkanImpresi();
}

function jadwalkanImpresi() {
  clearTimeout(pengaturImpresi);
  const sejakFlush = Date.now() - waktuFlushTerakhir;
  pengaturImpresi = setTimeout(flushImpresi, sejakFlush >= MAKS_MENAHAN ? 0 : JEDA_DIAM);
}

function flushImpresi() {
  if (!antreanImpresi.size) return;
  const ids = [...antreanImpresi];
  antreanImpresi.clear();
  waktuFlushTerakhir = Date.now();
  kirim('impression', { produk: ids });
}

// Jangan sampai impresi terakhir hilang saat tab disembunyikan/ditutup.
document.addEventListener('visibilitychange', () => { if (document.hidden) flushImpresi(); });
window.addEventListener('pagehide', flushImpresi);

export function mulaiTelemetri() {
  inisialisasiPekerja();
}

// Fungsi bantu yang dipakai di banyak tempat.

export const $ = (selektor, akar = document) => akar.querySelector(selektor);

export function el(tag, kelas, teks) {
  const node = document.createElement(tag);
  if (kelas) node.className = kelas;
  if (teks !== undefined) node.textContent = teks;
  return node;
}

// Dibuat sekali di scope modul. Membuat Intl.NumberFormat baru tiap panggilan
// sangat mahal (dipanggil ribuan kali saat menggambar kartu).
const PEMFORMAT_RUPIAH = new Intl.NumberFormat('id-ID', {
  style: 'currency',
  currency: 'IDR',
  maximumFractionDigits: 0,
});

export function formatRupiah(angka) {
  return PEMFORMAT_RUPIAH.format(angka);
}

// Menunda pemanggilan sampai tidak ada pemanggilan baru selama `jeda` ms.
// Dipakai untuk input pencarian supaya tiap huruf tidak memicu render penuh.
export function debounce(fn, jeda) {
  let pengatur;
  return function (...args) {
    clearTimeout(pengatur);
    pengatur = setTimeout(() => fn.apply(this, args), jeda);
  };
}

// Menjalankan fn paling banyak sekali per frame (rendering opportunity).
// Dipakai untuk handler gulir supaya event yang menumpuk digabung jadi satu.
export function rafThrottle(fn) {
  let menunggu = false;
  let argumenTerakhir;
  return function (...args) {
    argumenTerakhir = args;
    if (menunggu) return;
    menunggu = true;
    requestAnimationFrame(() => {
      menunggu = false;
      fn.apply(this, argumenTerakhir);
    });
  };
}

export function formatRibuan(angka) {
  if (angka >= 1000) return (Math.floor(angka / 100) / 10).toLocaleString('id-ID') + ' rb';
  return String(angka);
}

export function hargaSetelahDiskon(produk) {
  return Math.round((produk.harga * (100 - produk.diskon)) / 100 / 100) * 100;
}

// Salinan dalam (deep copy) supaya objek konfigurasi tidak termutasi.
export function salinDalam(objek) {
  return JSON.parse(JSON.stringify(objek));
}

// Pengurutan sederhana, dipakai untuk daftar pendek di bagian kaki halaman.
export function urutkanGelembung(daftar, banding) {
  const hasil = daftar.slice();
  for (let i = 0; i < hasil.length; i++) {
    for (let j = 0; j < hasil.length - i - 1; j++) {
      if (banding(hasil[j], hasil[j + 1]) > 0) {
        const tmp = hasil[j];
        hasil[j] = hasil[j + 1];
        hasil[j + 1] = tmp;
      }
    }
  }
  return hasil;
}

let pengaturWaktuToast;
export function tampilkanToast(pesan) {
  const toast = $('#toast');
  toast.textContent = pesan;
  toast.classList.add('tampil');
  clearTimeout(pengaturWaktuToast);
  pengaturWaktuToast = setTimeout(() => toast.classList.remove('tampil'), 2600);
}

/**
 * ALAT UKUR (bukan bagian dari aplikasi; tidak perlu "diperbaiki").
 * Aktif dengan membuka http://localhost:3000/?ukur=1
 *
 * Menampilkan ringkasan: long task, perkiraan INP, CLS, dan frame lambat.
 * Angka di sini untuk memantau cepat. BUKTI diagnosis tetap harus dari
 * panel Performance di DevTools (flame chart), bukan dari panel ini.
 */
(() => {
  const data = {
    longTask: [],            // durasi (ms)
    interaksi: new Map(),    // interactionId -> { durasi, jenis, target }
    cls: 0, clsSesi: 0, clsTerakhir: 0, clsAwalSesi: 0,
    frameLambat: 0, frameTerburuk: 0,
  };

  const dukung = (jenis) => (PerformanceObserver.supportedEntryTypes || []).includes(jenis);

  if (dukung('longtask')) {
    new PerformanceObserver((l) => l.getEntries().forEach((e) => data.longTask.push(Math.round(e.duration))))
      .observe({ type: 'longtask', buffered: true });
  }

  if (dukung('event')) {
    new PerformanceObserver((l) => {
      for (const e of l.getEntries()) {
        if (!e.interactionId) continue;
        const lama = data.interaksi.get(e.interactionId);
        if (!lama || e.duration > lama.durasi) {
          const t = e.target;
          data.interaksi.set(e.interactionId, {
            durasi: Math.round(e.duration),
            jenis: e.name,
            target: t ? (t.id ? '#' + t.id : t.className ? '.' + String(t.className).split(' ')[0] : t.tagName.toLowerCase()) : '?',
            tundaInput: Math.round(e.processingStart - e.startTime),
            proses: Math.round(e.processingEnd - e.processingStart),
            presentasi: Math.round(e.startTime + e.duration - e.processingEnd),
          });
        }
      }
    }).observe({ type: 'event', durationThreshold: 16, buffered: true });
  }

  if (dukung('layout-shift')) {
    new PerformanceObserver((l) => {
      for (const e of l.getEntries()) {
        if (e.hadRecentInput) continue;
        // jendela sesi: jeda < 1 dtk, panjang maks 5 dtk (definisi CLS)
        if (e.startTime - data.clsTerakhir < 1000 && e.startTime - data.clsAwalSesi < 5000) data.clsSesi += e.value;
        else { data.clsSesi = e.value; data.clsAwalSesi = e.startTime; }
        data.clsTerakhir = e.startTime;
        if (data.clsSesi > data.cls) data.cls = data.clsSesi;
      }
    }).observe({ type: 'layout-shift', buffered: true });
  }

  let tSebelum = performance.now();
  const pantauFrame = (t) => {
    const selisih = t - tSebelum;
    tSebelum = t;
    if (selisih > 50) { data.frameLambat++; if (selisih > data.frameTerburuk) data.frameTerburuk = Math.round(selisih); }
    requestAnimationFrame(pantauFrame);
  };
  requestAnimationFrame(pantauFrame);

  function ringkas() {
    const durasi = [...data.interaksi.values()].sort((a, b) => b.durasi - a.durasi);
    // INP ~ interaksi terburuk (abaikan 1 terburuk per 50 interaksi)
    const inp = durasi.length ? durasi[Math.min(Math.floor(durasi.length / 50), durasi.length - 1)] : null;
    return {
      waktu: new Date().toISOString(),
      jumlahLongTask: data.longTask.length,
      longTaskTerlama: data.longTask.length ? Math.max(...data.longTask) : 0,
      totalBlokir: data.longTask.reduce((n, d) => n + Math.max(d - 50, 0), 0),
      jumlahInteraksi: durasi.length,
      inp: inp ? inp.durasi : null,
      inpRinci: inp,
      limaInteraksiTerlambat: durasi.slice(0, 5),
      cls: Math.round(data.cls * 1000) / 1000,
      frameLambat: data.frameLambat,
      frameTerburuk: data.frameTerburuk,
    };
  }

  // ---------- tampilan ----------
  const panel = document.createElement('div');
  panel.id = 'alat-ukur';
  panel.style.cssText = 'position:fixed;left:10px;bottom:10px;z-index:9999;width:268px;max-width:calc(100vw - 20px);padding:10px 12px;border-radius:10px;background:rgba(20,18,43,.94);color:#fff;font:12px/1.5 ui-monospace,Menlo,Consolas,monospace;contain:layout paint;';
  panel.innerHTML = '<div id="au-isi"></div><div style="display:flex;gap:6px;margin-top:8px"><button id="au-salin" type="button">Salin JSON</button><button id="au-reset" type="button">Reset</button><button id="au-kecil" type="button">Kecilkan</button></div>';
  let kecil = window.innerWidth < 600; // di layar sempit mulai dalam keadaan kecil
  document.body.append(panel);
  panel.querySelectorAll('button').forEach((b) => { b.style.cssText = 'flex:1;border:0;border-radius:6px;padding:5px;background:#ffd400;color:#14122b;font:inherit;font-weight:700;cursor:pointer'; });

  const warna = (nilai, baik, buruk) => (nilai == null ? '#aaa' : nilai <= baik ? '#5ee0a0' : nilai <= buruk ? '#ffd400' : '#ff6b81');
  const isi = panel.querySelector('#au-isi');
  function gambar() {
    const r = ringkas();
    panel.querySelector('#au-salin').style.display = panel.querySelector('#au-reset').style.display = kecil ? 'none' : '';
    panel.querySelector('#au-kecil').textContent = kecil ? 'Buka alat ukur' : 'Kecilkan';
    if (kecil) {
      isi.innerHTML = `INP <span style="color:${warna(r.inp, 200, 500)}">${r.inp ?? '-'}</span> | CLS <span style="color:${warna(r.cls, 0.1, 0.25)}">${r.cls}</span> | LT <span style="color:${warna(r.longTaskTerlama, 100, 300)}">${r.longTaskTerlama}</span>`;
      return;
    }
    isi.innerHTML =
      `<b>Alat ukur TokoKilat</b><br>` +
      `INP&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: <span style="color:${warna(r.inp, 200, 500)}">${r.inp ?? '-'} ms</span> (${r.jumlahInteraksi} interaksi)<br>` +
      `CLS&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: <span style="color:${warna(r.cls, 0.1, 0.25)}">${r.cls}</span><br>` +
      `Long task : ${r.jumlahLongTask}x, terlama <span style="color:${warna(r.longTaskTerlama, 100, 300)}">${r.longTaskTerlama} ms</span><br>` +
      `Blokir&nbsp;&nbsp;&nbsp;&nbsp;: ${r.totalBlokir} ms total<br>` +
      `Frame &gt;50ms: ${r.frameLambat}x, terburuk ${r.frameTerburuk} ms`;
  }
  setInterval(gambar, 1000);
  gambar();

  panel.querySelector('#au-salin').addEventListener('click', async () => {
    const teks = JSON.stringify(ringkas(), null, 2);
    try { await navigator.clipboard.writeText(teks); } catch { /* abaikan */ }
    console.log('[alat ukur]\n' + teks);
  });
  panel.querySelector('#au-kecil').addEventListener('click', () => { kecil = !kecil; gambar(); });
  panel.querySelector('#au-reset').addEventListener('click', () => {
    data.longTask.length = 0; data.interaksi.clear();
    data.cls = data.clsSesi = 0; data.frameLambat = data.frameTerburuk = 0;
    gambar();
  });

  window.AlatUkur = { ringkas };
})();

// Worker analitik.
//
// SDK vendor (lacak.min.js) menghitung hash tetap 2.000.000 iterasi pada setiap
// panggilan kirim(), sehingga satu panggilan memakan ~90 ms di CPU 4x dan
// memblokir main thread (terbukti di flame chart: fungsi `k @ lacak.min.js`).
//
// Worker ini memuat SDK vendor APA ADANYA (berkas tidak diubah), tetapi
// menjalankannya di thread terpisah sehingga biaya hashing tidak lagi memblokir
// UI. SDK mengakses window/document/screen/navigator, jadi disediakan tiruan
// (shim) minimal sebelum SDK dimuat. Setiap event tetap dikirim lewat API SDK.

self.window = self;

let lokasiPath = '/';
let layar = { width: 0, height: 0, colorDepth: 24 };

self.document = { location: { get pathname() { return lokasiPath; } } };

try {
  if (typeof self.screen === 'undefined') {
    Object.defineProperty(self, 'screen', {
      configurable: true,
      get() { return layar; },
    });
  }
} catch { /* biarkan; sebagian lingkungan sudah menyediakan screen */ }

importScripts('/vendor/lacak.min.js');

self.onmessage = (e) => {
  const pesan = e.data || {};
  if (pesan.init) {
    lokasiPath = pesan.init.pathname || '/';
    if (pesan.init.screen) layar = pesan.init.screen;
    return;
  }
  if (self.Lacak) {
    self.Lacak.kirim(pesan.nama, pesan.data);
    self.postMessage({ terkirim: pesan.nama, total: self.Lacak.antrian.length });
  }
};
